window.YOOPER = window.YOOPER || {};
window.YOOPER.WATER_WAR_TIERS = Object.assign(window.YOOPER.WATER_WAR_TIERS || {}, {
  "No Water Drawn": { label: "No Water Drawn", desc: "It’s 68 degrees and nobody wants to get wet, ya know. Da garden hose stays coiled in 14 loops on its reel, da balloons stay sealed in dere bag of 100, and da only water in play is a glass on da porch rail nobody’s touched in 40 minutes. Zero throws tried, zero landed. Da summer opens wit’ da ledger blank." },
  "Condensation Ring": { label: "Condensation Ring", desc: "Da first moisture of da war is a ring on da patio table, 3 inches across, left by a glass of iced tea. Somebody drags a finger through it and flicks roughly 0.05 mL at a sibling from 2 feet away. Da sibling reports no contact. Da glass gets moved to a coaster, and da front goes quiet da rest of da afternoon." },
  "Dewdrop Dare": { label: "Dewdrop Dare", desc: "At 7:15 in da morning da lawn’s got dew on it, and somebody gets dared to cross it barefoot. Da crossing is 22 feet, takes 9 seconds, and leaves both feet soaked to da ankle. One side calls it an act of war, da other calls it weather. Da fight outlasts da dew, which is gone by 9:40." },
  "Flicked Fingertip": { label: "Flicked Fingertip", desc: "A wet fingertip gets flicked at da back of a neck, deliverin’ an estimated 3 drops at point-blank range. Da target turns around, finds 4 likely suspects, and blames da wrong one. Payback comes inside 90 seconds, also by fingertip and also at da wrong guy. By supper da kitchen has split into 2 camps over a combined 7 drops." },
  "Ice Cube Down the Back": { label: "Ice Cube Down Da Back", desc: "Da first real projectile is an ice cube: about 1 ounce at 32 degrees, dropped down da back of a shirt instead of thrown. It melts in roughly 4 minutes and leaves a wet stripe 11 inches long. Da victim screams at a pitch ya can hear 2 houses over, which da perpetrator logs as a confirmed hit." },
  "Fountain Thumb": { label: "Fountain Thumb", desc: "At da park drinkin’ fountain, a thumb over da spout turns a 2-foot drinkin’ arc into a flat spray reachin’ 6 feet. It gets 3 people waitin’ in line and 1 fella who was just walkin’ by. Everybody agrees da fountain is neutral ground, den da same thumb uses it again 11 minutes later." },
  "Glass Tipped": { label: "Glass Tipped", desc: "Half a glass of water, about 4 ounces, gets tipped over a sibling’s head at da supper table. It’s premeditated, takes roughly 1.5 seconds, and 2 parents see da whole t’ing. Both rule against da tipper, and da war’s first sanction comes down: no dessert for 1 night. Da sibling figures dat’s not near enough, eh." },
  "Puddle Stomp": { label: "Puddle Stomp", desc: "A leftover sprinkler puddle, 18 inches across and half an inch deep, becomes da first contested ground. One stomp t’rows water about 3 feet every which way and soaks 2 pairs of socks, neither of ’em belongin’ to da stomper. Da puddle’s spent after 5 stomps. Nobody t’inks to refill it." },
  "Sketch of a Pump": { label: "Sketch of a Pump", desc: "Nobody’s fightin’, so somebody draws instead: a tube, a plunger, a handle, and an arrow labeled ‘water comes out here.’ At 4 squares to da inch da tube works out to a 1-inch bore wit’ a 6-inch stroke, or 4.7 cubic inches a pull, about 2.6 ounces. Nothin’ gets built. It’s da first page of a design record dat’ll outlast da weather." },
  "Wet Sponge Rumor": { label: "Wet Sponge Rumor", desc: "Word goes around dat somebody’s got a car-wash sponge soaked and ready, holdin’ roughly 8 ounces. Da story gets told 6 times in an hour and grows to 3 sponges and a bucket. No sponge ever shows up. Two kids change dere route home anyhow, addin’ 400 feet to da walk." },
  "Spray Bottle Found": { label: "Spray Bottle Found", desc: "A spray bottle turns up under da kitchen sink: 24 ounces, last used on da windows. At roughly 0.8 mL a pull it holds about 880 shots, more ammo dan da war’s used all month. Range is 9 feet on da stream setting. It gets rinsed twice before anybody agrees to point it at a person." },
  "Spray Bottle Skirmish": { label: "Spray Bottle Skirmish", desc: "Da spray bottle gets deployed. Over 20 minutes it fires 140 times, lands 31 hits, and drains by about a sixth. Da skirmish ends when da nozzle gets twisted to ‘mist’ by accident, cuttin’ range from 9 feet to 3 and da threat to zero. It’s da first fight anybody bothers to count." },
  "Mister Fan Duel": { label: "Mister Fan Duel", desc: "Two handheld battery fans wit’ mister tanks square off on da porch, each holdin’ about 3 ounces. On full dey t’row a fine mist roughly 2 feet, which is less dan da 5 feet between da chairs. After 14 minutes of steady fire both sides are measurably cooler and neither one is measurably wet. It’s scored a draw, and da batteries, 2 AA each, are da only casualties." },
  "Cup Toss": { label: "Cup Toss", desc: "Da first open-container attack: a plastic cup of about 8 ounces, tossed underhand across 4 feet of patio. Roughly 5 ounces reach da target, and da other 3 land on da t’rower’s own shoes. Da cup itself don’t get let go, which is later cited as proof of restraint. Payback comes inside 90 seconds, usin’ da same cup." },
  "Dixie Cup Volley": { label: "Dixie Cup Volley", desc: "At a church picnic, a stack of paper cone cups sits next to a 5-gallon water cooler, each cup holdin’ about 4 ounces. Ya can’t set a cone cup down, so every cup filled has gotta be used. 3 kids fire 22 cups in 6 minutes, drawin’ da cooler down about 0.7 gallons. A grown-up takes da cups; da cooler stays, and so does da problem." },
  "Water Bottle Squeeze": { label: "Water Bottle Squeeze", desc: "A half-liter plastic water bottle wit’ da cap off, squeezed hard, sends a stream about 7 feet. It empties in 4 squeezes and crackles loud on every one, which gives away each attack roughly 1 second early. It gets refilled at da kitchen sink 3 times before it splits along a seam. It’s da war’s first piece of gear retired from wear." },
  "Sports Bottle Squirt": { label: "Sports Bottle Squirt", desc: "Da sports bottle holds 24 ounces behind a pull-top valve and was built to be squeezed. A good squeeze reaches 12 feet, near double da plain water bottle, wit’ no crackle to warn anybody. Since ya can carry it closed, it comes along to a soccer game, where 9 ounces get spent on teammates durin’ 1 water break. Da coach hangs onto it till da second half." },
  "Garden Hose Left On": { label: "Garden Hose Left On", desc: "Da garden hose gets left runnin’ in da side yard after waterin’, at about 9 gallons a minute. By da time anybody notices, 40 minutes have gone by, about 360 gallons are gone, and a low spot in da lawn holds water 3 inches deep. Nobody sprayed nobody. It goes in da record anyhow. Cripes, 360 gallons is more dan da war’s used in its whole history." },
  "Hose Kink Ambush": { label: "Hose Kink Ambush", desc: "Da hose gets folded double 20 feet from da spigot, trappin’ about 50 psi behind da kink. A sibling holdin’ da dead nozzle turns it around to look in it. Da fold gets let go, and about 0.5 gallons show up in 3 seconds at a range of roughly 4 inches. It’s da first attack usin’ stored pressure, and it ain’t gonna work on dat sibling again." },
  "Thumb-over-Hose Fan": { label: "Thumb-over-Hose Fan", desc: "A thumb pressed over da open hose end turns 12 gallons a minute into a flat fan reachin’ about 15 feet, da longest reach yet. It covers a 90-degree arc and needs no aim, just a willingness to lose feelin’ in da thumb after 2 minutes. 4 targets get hit in one sweep of da driveway. Da thumb switches hands at da 3-minute mark, and accuracy drops by about half." },
  "Sprinkler Dash": { label: "Sprinkler Dash", desc: "An oscillatin’ sprinkler sweeps a 30-by-40-foot rectangle about once every 20 seconds. Da game is to cross it dry, and da record after 1 afternoon is 0 clean crossings in 47 tries. Da sprinkler don’t favor nobody, which makes it da war’s first impartial combatant. Overnight it gets moved 6 feet closer to da patio by somebody who’s picked a side." },
  "Car Wash Crossfire": { label: "Car Wash Crossfire", desc: "A family car wash wit’ 2 buckets and 1 hose turns into crossfire inside 8 minutes. Da driver’s side, which faced away from most of da shootin’, comes out cleaner dan da passenger side. About 70 gallons get used against a planned 25. Da sponge from da old rumor is confirmed real and gets t’rown 3 times." },
  "Dog Bowl Incident": { label: "Dog Bowl Incident", desc: "A full dog bowl, 2 quarts, gets picked up and t’rown mid-battle, da first time anybody’s used water dat belonged to somebody else. Da dog, 60 pounds, watches its bowl empty onto da neighbor kid and don’t take a side. Public opinion turns hard against da t’rower. Da bowl’s refilled inside 2 minutes, and da dog’s water is declared off-limits in da war’s first written rule." },
  "Kiddie Pool Splash": { label: "Kiddie Pool Splash", desc: "A 6-foot kiddie pool holdin’ about 100 gallons becomes da first reservoir dat don’t need a spigot. Two cupped hands move roughly 6 ounces a splash, so emptyin’ it dat way would take over 2,000 splashes. Nobody tries. Instead da pool becomes a base, and anybody standin’ in it counts as holdin’ a fortified position, even dough da water’s 10 inches deep." },
  "Pump Specs Drawn": { label: "Pump Specs Drawn", desc: "Da pump sketch gets redrawn to scale at 4 squares to da inch, dis time wit’ dimensions: a 1-inch bore, a 6-inch stroke, 4.7 cubic inches a pull, about 2.6 ounces. Dat’s 2 strokes to empty a 4-ounce cone cup and roughly 4,900 to empty a 100-gallon kiddie pool. A parts list follows: 1 length of 1-inch tube, 1 dowel, 2 rubber washers, and 1 check valve of unknown origin. Nothin’ built yet." },
  "Bucket Rumor": { label: "Bucket Rumor", desc: "Word goes around dat somebody on da next street has a 5-gallon bucket, which would hold 640 ounces, or about 160 cone cups at once. Nobody’s seen it. 3 different kids claim to know where it’s kept, and dere stories put it in 3 different garages. Defense plans get drawn up anyhow, mostly involvin’ runnin’." },
  "Dollar-Store Squirt Gun": { label: "Dollar-Store Squirt Gun", desc: "Da first purpose-built weapon shows up: a clear plastic squirt gun, $1, holdin’ about 1 ounce. It reaches 10 to 15 feet and gets roughly 30 pulls a fill, each one small enough da guy who got hit can deny it. Its main advantage is it looks like a weapon, which changes how everybody else acts. 4 more get bought da next afternoon." },
  "Leaky Trigger": { label: "Leaky Trigger", desc: "One squirt gun springs a leak at da trigger seal and loses about a third of its 1 ounce into da owner’s palm on da walk to da front. By da time da owner’s in range, 12 feet, it fires roughly 20 times instead of 30. Electrical tape gets put on twice, no good. Da owner is da wettest one in every fight, even da ones dey win." },
  "First Water Balloon": { label: "First Water Balloon", desc: "A pack of 50 water balloons turns up, and da first one gets filled at da bathroom sink to about 5 ounces in 5 seconds. Tyin’ it takes 40 seconds, ’cause nobody’s ever tied one. It gets carried outside in both hands at a walk, t’rown 20 feet, lands on grass, and don’t break. It gets t’rown again." },
  "Burst in Hand": { label: "Burst in Hand", desc: "Da second balloon gets filled to about 9 ounces, way past da usual 4 to 6, and pops while bein’ tied, dumpin’ da whole load into da filler’s lap from 0 inches. Of da next 10 balloons, 3 pop in hand, 2 pop on launch, and 5 reach a target. Da 50% failure rate gets wrote down. Fillin’ ’em outside is proposed and adopted right away." },
  "Knot-Tying Bottleneck": { label: "Knot-Tying Bottleneck", desc: "Fillin’ a balloon takes about 5 seconds; tyin’ it takes 8 to 10, and only 2 of da 6 fighters can tie at all. Output tops out at roughly 4 balloons a minute per tyer. Da front line t’rows faster dan dat, so da back line becomes a factory. Da best tyer gets pulled from combat entirely, a promotion dey never asked for." },
  "Refill Queue": { label: "Refill Queue", desc: "Dere’s 1 outdoor spigot and 5 people who need it. Da line forms at 2:15 and settles into a rotation of about 90 seconds a person, so each fighter waits 6 minutes to refill for roughly 2 minutes of fightin’. Line-cuttin’ gets tried twice and punished wit’ a cup of water each time. Da spigot, not any fighter, is now da most important spot in da yard." },
  "Truce at the Spigot": { label: "Truce at Da Spigot", desc: "A truce is called for everyt’ing inside 3 feet of da spigot: no firin’ while anybody’s fillin’. It holds 26 minutes, da longest ceasefire yet, and gets broke by a hose left hooked to da spigot dat was, technically, not fillin’ nothin’. A 15-minute argument follows over whether da hose counts as da spigot. It’s ruled dat it does, retroactively." },
  "Faucet Adapter": { label: "Faucet Adapter", desc: "A $4 faucet adapter lets balloons fill straight from da kitchen tap, endin’ da spigot’s monopoly. Da house now has 2 fill points and a parent who agreed to neither one. About 1 in 8 balloons slips off da adapter early and fills da sink instead. Turns out da spigot truce don’t reach da kitchen, which somebody finds out da hard way." },
  "Wet Shirt Surrender": { label: "Wet Shirt Surrender", desc: "Da first formal surrender: a fighter whose shirt has soaked up an estimated 20 ounces, enough to hang 2 inches lower dan it did at noon, walks to da middle of da yard and wrings it out. Da wringin’ is accepted as capitulation. Terms are generous: 10 minutes of amnesty and first place in da refill line. Da shirt’s on da fence by 4:00 and dry by 4:40." },
  "Towel Neutrality": { label: "Towel Neutrality", desc: "Towels get declared neutral: anybody holdin’ one can’t be targeted, and 3 are hung on da porch rail for everybody. By 5:00 da rule’s been abused 6 times, mostly by fighters carryin’ a towel into position and droppin’ it 10 feet from a target. So neutrality gets limited to towels on da porch itself. A dry towel now trades for about da value of a full squirt gun." },
  "Balloon Bucket": { label: "Balloon Bucket", desc: "A real 5-gallon bucket, da one from da rumor or one like it, gets filled halfway wit’ water and stocked wit’ 60 tied balloons, da water cushionin’ ’em. 2 tyers fill it in about 8 minutes, and it weighs roughly 40 pounds. For da first time, ammo gets made before da fightin’ instead of durin’ it. It takes 2 people to carry, which is how da war finds out it’s got logistics." },
  "Balloon Brigade": { label: "Balloon Brigade", desc: "Da balloon bucket gets a crew. 4 kids make a line from da spigot to da fence: 1 fills, 1 ties, 1 carries, and 1 t’rows, at a steady 6 balloons a minute. Da line breaks down at da tyin’ station, where each knot takes 11 seconds and 1 balloon in 5 pops in hand. Da tyer ends up wetter dan any target." },
  "Sprinkler Fort": { label: "Sprinkler Fort", desc: "An oscillatin’ sprinkler gets set in da middle of da yard, and its 40-foot sweep is declared a fort. Anybody inside da arc counts as defended, and anybody outside counts as dry, which is worse. Da defenders learn da cycle, 18 seconds side to side, and time dere dashes to it. Nobody attacks da fort, ’cause nobody can figure out whose side da sprinkler’s on." },
  "Kiddie Pool Keep": { label: "Kiddie Pool Keep", desc: "A 6-foot plastic kiddie pool, filled to 8 inches wit’ about 140 gallons, becomes da keep: da one water supply everybody’s gotta come back to. It’s held by 2 defenders who sit in it and won’t get out. Attackers dip cups over da rim at a cost of 1 splash per dip. By late afternoon da water’s 84 degrees wit’ 14 grass clippings in it, and dey defend it anyhow." },
  "Slip 'n Slide Front": { label: "Slip ’n Slide Front", desc: "A 25-foot slide mat gets unrolled down da gentle slope of da yard and wetted wit’ da hose, openin’ da first front wit’ a direction. A run takes about 3 seconds and ends in a flowerbed 4 feet past da mat. Da mat’s a supply route and an ambush point at once, since whoever’s lyin’ at da bottom gets hit by whoever launches next. Casualties are grass stains, 9 by count, all on da same pair of shorts." },
  "Tarp Slide": { label: "Tarp Slide", desc: "Da mat’s judged too short, so a 20-by-40-foot blue tarp from da garage replaces it, weighed down at da corners wit’ 4 bricks and slicked wit’ a squirt of dish soap. Length goes up 15 feet and friction goes down by an amount nobody measures. One slider leaves da tarp entirely and keeps goin’ 11 feet across da lawn. Da bricks get moved in and da tarp gets renamed a runway." },
  "Hose Artillery": { label: "Hose Artillery", desc: "Da garden hose enters da war as artillery. At 12 gallons a minute on da jet setting it t’rows a stream about 35 feet, outrangin’ everyt’ing else in da yard by a factor of 3. It also has a 50-foot tether and one operator who can’t chase nobody. Da first volley soaks 3 targets and 1 open kitchen window." },
  "Nozzle Settings Treaty": { label: "Nozzle Settings Treaty", desc: "Da hose nozzle’s got 8 settings, and after da window deal all 8 get negotiated. Jet is banned inside 15 feet. Shower, mist, and cone are allowed everywhere. Flat, soaker, and center are allowed even dough nobody knows what dey do, and full is saved for fillin’ da kiddie pool. Da treaty’s wrote on a paper plate and signed by 5 parties, 1 of ’em in crayon." },
  "Squirt Pistol Pair": { label: "Squirt Pistol Pair", desc: "2 matchin’ squirt pistols show up, bought at a gas station for $2.49 apiece. Each holds about 3 ounces and shoots 12 feet at roughly 0.2 ounces a pull, so a full tank lasts 15 pulls. Da owner carries both, one in each hand, and is empty in 40 seconds. Den da owner spends 4 minutes at da spigot refillin’ ’em, which is right where da owner gets ambushed." },
  "Pump-Action Prototype": { label: "Pump-Action Prototype", desc: "Da graph-paper design finally gets built outta PVC pipe: a 1-inch bore, a 6-inch stroke, and 2.6 ounces a stroke, just like it was drawn at 4 squares to da inch. It takes 2 afternoons, 1 hacksaw, and $11.40 in fittings, and da plunger seal is a trimmed faucet washer. A full pull reaches about 30 feet. Da first shot works, da second leaks at da elbow, and nobody dere doubts da design again." },
  "Pressure Chamber Debate": { label: "Pressure Chamber Debate", desc: "Da prototype fires one stroke at a time, so somebody proposes addin’ an air chamber so ya can pump it ahead. Da yes side cites a 2-liter pop bottle, which holds way past 100 psi before it bursts. Da no side cites da same bottle and asks what happens at da burst. Da debate runs 45 minutes across 2 porches and ends wit’out a vote when a parent puts da bottle in da recycling." },
  "Backpack Tank": { label: "Backpack Tank", desc: "Range ain’t da problem no more; refills are. A 3-liter water bladder from a hikin’ pack gets filled and run t’rough 4 feet of tubing to a squirt pistol, which now don’t run dry for about 500 pulls. Loaded, da rig weighs about 8 pounds and sloshes loud, so forget sneakin’ up on anybody. Da wearer still gets hit first, ’cause da pack makes one big target." },
  "Ice Water Escalation": { label: "Ice Water Escalation", desc: "A cooler of ice water at about 34 degrees joins da arsenal, cold like Lake Superior in August, and every weapon filled from it changes category. A 3-ounce hit dat was refreshin’ at 72 degrees now gets a scream ya can hear 2 houses down. Da first complaint comes in inside 6 minutes. Ice water ain’t banned, but it’s logged, and from here on every tank gets asked its temperature before it’s allowed to fire." },
  "Three-Person Balloon Launcher": { label: "Three-Person Balloon Launcher", desc: "A surgical-tubing launcher shows up: 2 people hold da handles, and a third pulls da pouch back 8 feet and lets go. Da first balloon clears da yard, da next yard, and da street, landin’ about 300 feet away on a parked car nobody recognizes. At dat range accuracy is measured in property lines. Da crew agrees to fire only inside da fence, which caps range at 90 feet and wastes 70 percent of da launcher." },
  "Trampoline Sprinkler": { label: "Trampoline Sprinkler", desc: "A sprinkler gets set under da 14-foot trampoline, turnin’ it into a platform dat’s both up high and wet for good. Jumpers gain about 4 feet of height, which makes ’em harder to hit and easier to see. T’rows from da mat come down steep, over any cover in da yard. Da platform holds 25 minutes, till 3 jumpers land on da same spot and 1 gets ejected onto da lawn, damp but not hurt." },
  "Fence Line Ambush": { label: "Fence Line Ambush", desc: "Da first cross-yard attack goes over da 6-foot privacy fence. 2 attackers standin’ on flipped buckets lob 9 balloons blind into da next yard, where a family’s eatin’ corn at a picnic table. 4 hit da grass, 3 hit da table, 1 hits da corn, and 1 lands on da grill, which hisses. Payback don’t come right away, which is more worryin’ dan if it did." },
  "Two-Yard War": { label: "Two-Yard War", desc: "Da neighbors answer wit’ dere own hose, dere own balloons, and 3 cousins visitin’ from down below. Da war now spans 2 yards, 1 fence, and roughly 11,000 square feet of lawn. A gate halfway down da fence is da only crossin’, and it changes hands 6 times in an hour. Both water meters are spinnin’ at once for da first time, and neither family’s looked at either one." },
  "Water Table Seized": { label: "Water Table Seized", desc: "Da heat index is past 100 and nobody’s runnin’ no more. Da prize ain’t a yard now but da plastic water table on da patio: 2 gallons across 3 basins, rated for ages 18 months and up, sittin’ in da only shade on either lot. 2 kids seize it, kneel over it, and ration it by da cupful. A grown-up puts in da one rule nobody argues wit’: a drink of actual water every 20 minutes. Da seizure is allowed to stand." },
  "Rain Barrel Claimed": { label: "Rain Barrel Claimed", desc: "Da rain barrel under da garage downspout, rated at 55 gallons and last filled 19 days ago, gets claimed as a strategic reserve. It holds 41 gallons of water da color of weak tea and 1 drowned wasp. Da spigot at da bottom puts out about 2 gallons a minute, too slow to fight wit’ and too much to ignore. A parent contests da claim, sayin’ da barrel’s for da tomatoes, and da tomatoes win." },
  "Garage Armory": { label: "Garage Armory", desc: "Da garage gets turned into an armory. Inspection finds 1 waterin’ can, 3 empty paint buckets, a 2-gallon pump sprayer dat last held weed killer, a turkey baster, and 60 feet of spare hose nobody knew was dere. Da sprayer gets rinsed 4 times and still rejected. Da armory is guarded by da family dog, who’s got no opinion on da war and sleeps t’rough da inventory." },
  "Bucket Brigade": { label: "Bucket Brigade", desc: "Wit’ da armory open, da line graduates from balloons to buckets. 5 kids pass 2-gallon paint buckets hand to hand across 60 feet from da spigot to da front, losin’ about a quarter of every load to sloshin’. Each bucket dat makes it gets t’rown in one motion and is spent in 1 second. Da oldest kid notices da ratio of work to effect, and everybody else ignores it." },
  "Five-Gallon Dump": { label: "Five-Gallon Dump", desc: "A full 5-gallon bucket weighs about 42 pounds, and it takes 2 kids to lift one to da edge of da trampoline. It gets tipped over da side onto 1 target standin’ right below. Da dump lasts under 2 seconds and beats da old record, a sloshed-down paint bucket, by about 42 pounds to 12. Holy wah. Da target don’t move for 5 full seconds, den asks, real calm, for a turn." },
  "Cooler Raid": { label: "Cooler Raid", desc: "Da drink cooler on da porch, 48 quarts of cans and ice, gets raided. Da objective ain’t da drinks but da meltwater: about 3 gallons at 34 degrees, bailed into 2 buckets while da grown-ups are inside. Da raid takes 90 seconds. Da 11 cans left behind sit in a dry cooler in da sun, warmin’ at a rate da grown-ups notice around da 20-minute mark." },
  "Popsicle Ceasefire": { label: "Popsicle Ceasefire", desc: "A box of 24 popsicles comes outta da freezer, and all fire stops inside 15 seconds. Da ceasefire is total and enforced by da popsicles demselves, which drip about once every 3 seconds in da heat and need both hands. It lasts 7 minutes, how long it takes da slowest eater to get to da stick. Dat eater reads da joke on da stick out loud to no reaction, and da fightin’ starts up again." },
  "No-Faces Rule": { label: "No-Faces Rule", desc: "After a direct hit to an eye from 6 feet, da first rule of engagement goes in: no faces. Targetin’ is limited to da band between shoulders and knees, roughly 2 feet tall on da average fighter. Hit rates drop about 30 percent. Da rule gets broke 4 times in da first hour, each time explained by da shooter as da target duckin’ wrong." },
  "Sunscreen Truce": { label: "Sunscreen Truce", desc: "A parent announces sunscreen, and a mandatory truce holds while 6 kids get lined up and coated in SPF 50. Each one takes about 40 seconds, uses roughly 1 ounce, and gets resisted. Wet kids gotta be dried first, which needs towels, which are already wet. Da truce lasts 12 minutes. Da label says reapply after 80 minutes in water, and nobody’s keepin’ time." },
  "Screen Door Neutral Zone": { label: "Screen Door Neutral Zone", desc: "Da back screen door gets declared neutral: anybody inside 3 feet of it can’t be targeted, ’cause a parent’s on da other side. Inside 10 minutes a kid exploits da zone by standin’ in it for 26 minutes wit’ a full pistol, waitin’. Da door itself takes 2 stray balloons, and da screen lets about half of each one t’rough into da kitchen." },
  "Wet Towel Ban": { label: "Wet Towel Ban", desc: "Da wet towel gets weaponized and banned da same afternoon. A beach towel, twisted and soaked, snaps wit’ about 2 feet of reach and leaves a red mark roughly 3 inches long. It’s ruled a melee weapon and outside da spirit of a water war. Towels are limited to dryin’, and da count of dry towels drops from 8 to 1 inside da hour anyhow." },
  "Chlorine Tag": { label: "Chlorine Tag", desc: "Da backyard pool opens: 18,000 gallons at 84 degrees and 3 parts per million chlorine. Da war moves into it and turns into tag, where whoever’s ‘it’ has gotta land a splash on somebody inside arm’s reach. Da no-faces rule gets suspended in da water by a vote of 5 to 2, since every face is already wet. Eyes are red by da 40-minute mark." },
  "Cannonball Contest": { label: "Cannonball Contest", desc: "A cannonball contest is held to settle, by splash, who controls da deep end. 7 entrants jump off da edge and get judged on how far da water carries across da deck. Da winner, at 94 pounds, puts water 14 feet across da patio and onto a lawn chair wit’ a phone on it. Da phone survives. Da result is ruled bindin’, and da deep end changes hands." },
  "Diving Board Command": { label: "Diving Board Command", desc: "Da divin’ board, 8 feet long and 1 meter over da water, becomes da command post. Whoever holds it sees da whole pool and can fire down on anybody who surfaces inside 10 feet. Da cannonball winner holds it and gives 12 orders in da first 5 minutes, 3 of which get followed. Da board’s lost only when da commander gets dared to try a backflip and says yah." },
  "Pool Noodle Cannon": { label: "Pool Noodle Cannon", desc: "A pool noodle, 5 feet long wit’ a hollow core just under 1 inch across, gets filled underwater, capped wit’ a palm, and fired by blowin’ hard in da other end. Da shot reaches about 8 feet and delivers roughly 2 cups. Da operator swallows some of da pool 3 times in 10 shots. Somebody notices da core is near da pump’s bore and goes lookin’ for a broom handle." },
  "Water Blob": { label: "Water Blob", desc: "A water blob gets built: 2 plastic sheets, 10 by 20 feet, taped along all 4 edges wit’ 3 rolls of duct tape and filled from da hose for 50 minutes. It holds about 500 gallons and weighs roughly 2 tons. It’s terrain, not a weapon, since anybody standin’ on it can get launched off by anybody jumpin’ on it. It leaks from 1 corner at about a cup a minute, and dat corner’s guarded." },
  "Splash Radius": { label: "Splash Radius", desc: "For da first time, damage gets measured as an area. 3 kids jump on da blob at once and t’row water out in a ring, and somebody paces it off: 17 feet every direction, about 900 square feet. Everyt’ing inside da circle is presumed wet, includin’ 2 foldin’ chairs, a bag of chips, and da last dry towel. From here on, weapons get rated by radius as well as range." },
  "Dripping Retreat": { label: "Dripping Retreat", desc: "Da first organized retreat: da losin’ side pulls back from da pool deck to da side yard, leavin’ a trail of drips showin’ exactly where it went. A fighter fresh outta da pool sheds about 1 cup of water in da first 30 seconds on land, enough to mark 40 feet of concrete. Da chasers follow da trail at a walk. In dis heat it dries up in about 6 minutes, which is how long da retreat has to regroup." },
  "Kitchen Sink Supply Line": { label: "Kitchen Sink Supply Line", desc: "Da spigot’s overbooked, so a second supply line opens t’rough da house. Da kitchen sink sprayer gets pulled out its full 3 feet and aimed out da window into waitin’ buckets at about 1.5 gallons a minute, slower dan da outdoor tap but closer to da ice maker. Da line runs 17 minutes before da counter, da floor, and 1 grown-up are found wet." },
  "Soaker Showroom": { label: "Soaker Showroom", desc: "An errand to da store goes past an aisle of pressurized soakers priced from $14 to $49, each rated at 30 to 40 feet from a tank of 1 to 2 liters. 3 kids stand in front of it for 22 minutes readin’ da boxes. Dey got $8.75 between ’em. Nothin’ gets bought, but every spec gets memorized, and da PVC prototype, at 30 feet, is now known to be just average." },
  "Refill Station": { label: "Refill Station", desc: "A refill station gets set up at da spigot: a Y-splitter, 2 short hoses, and a posted rule of 1 minute a person, den back of da line. Wit’ da tap’s 12 gallons a minute split 2 ways, a 3-liter bladder fills in about 8 seconds and a pistol in under 1. So da line is mostly people arguin’ about da minute. It’s da first shared infrastructure of da war and right away da most contested ground in da yard." },
  "Sprinkler Timer Sabotage": { label: "Sprinkler Timer Sabotage", desc: "Somebody finds da lawn sprinkler controller in da garage and reprograms zone 3 to run at 4:15 for 20 minutes. Da first cycle catches da other side mid-refill and soaks 5 of ’em from 6 buried heads. Nobody suspects sabotage till 4:15 da next mornin’, when zone 3 runs again, set for both halves of da clock, under a row of open bedroom windows." },
  "Dunk Tank Tribunal": { label: "Dunk Tank Tribunal", desc: "A tribunal of 3 judges on a picnic bench hears da sabotage case. Da sentence is a dunk tank: da defendant sits on a plank across da kiddie pool, and da trigger is a pie tin nailed to a stake 20 feet away. Da first 11 t’rows miss, da 12th hits, and da defendant drops into 8 inches of 88-degree water. Dere’s no appeal, since it’s da coolest anybody’s been all day." },
  "Backyard Hegemony": { label: "Backyard Hegemony", desc: "By 7 in da evenin’ one yard holds everyt’ing dat matters: da pool, da blob, da refill station, da pump prototype, and 14 of da 19 active fighters. Da other yards still got water but nobody left to t’row it. Terms get dictated from da divin’ board and are generous, ’cause da hegemon needs everybody back tomorrow. At sunset it’s still 89 degrees, and 3 driveways down, a car is unloadin’ a box of pressurized soakers." },
  "Super Soakers Arrive": { label: "Super Soakers Arrive", desc: "Da first pressurized soaker comes to da block in a box marked for ages 8 and up, carried by a kid who’s 7. Its tank holds 2.5 liters, and after 12 pumps it t’rows a stream about 50 feet, farther dan anyt’ing ever fired on da street. Every spray bottle inside 3 houses is obsolete by 2:15 dat afternoon. Nobody surrenders, but a few kids go inside to ask about dere birthdays." },
  "Pressure Wars": { label: "Pressure Wars", desc: "By da end of da week 4 soakers are in service, and da argument moves from who gets wet to how many pumps each owner puts in before firin’. One kid pumps 40 times and claims da block record; another pumps 55 and a seam starts to weep. Range quits improvin’ at around 50 feet no matter what anybody does. Dis gets wrote down but nobody believes it." },
  "Tank Capacity Race": { label: "Tank Capacity Race", desc: "Range has topped out, so da contest moves to endurance. A 2-liter tank lasts about 90 seconds of steady fire, so a rival duct-tapes a 3-liter pop bottle to da stock as a reserve and advertises 3 minutes. Da taped rig weighs 7 pounds loaded and can’t be aimed above da shoulder. It still wins its first fight, by attrition, against a kid who ran dry at da mailbox." },
  "Cul-de-Sac Front": { label: "Cul-de-Sac Front", desc: "Da fightin’ bunches up around da cul-de-sac, a circle 80 feet across wit’ 6 driveways openin’ onto it. Each household holds its own driveway and treats da middle as open ground. Da storm drain in da center takes an estimated 40 gallons over da weekend. A parked minivan gets hit 19 times and later turns out to belong to somebody just visitin’." },
  "Block Alliance": { label: "Block Alliance", desc: "Three yards on da east side sign a pact on da back of a cereal box: shared ammo, shared refill rights, and no firin’ across each other’s property lines. Da alliance fields 9 fighters against da west side’s 5. Inside 2 days da west side makes its own pact on a pizza box, which is bigger, and dey count dat as a point in dere favor." },
  "Sidewalk No-Man's-Land": { label: "Sidewalk No-Man’s-Land", desc: "Da 4-foot public sidewalk between da two alliances becomes ground neither side can hold. Anybody on it is in range of both sides at once, includin’ a mail carrier who gets hit twice and a fella walkin’ a dog, which gets hit 3 times. A chalk line gets drawn down da middle. Da mail comes da next day by somebody walkin’ in da street." },
  "Garden Hose Network": { label: "Garden Hose Network", desc: "Da east alliance hooks 3 garden hoses end to end, 150 feet total, so one spigot can reach da front line. Flow at da far nozzle drops by about half, from a usable 9 gallons a minute to a sulkin’ 4 or so. Da couplin’ in da middle leaks steady onto a flower bed dat never did nothin’ to nobody. It’s da first infrastructure project of da war." },
  "Splitter Manifold": { label: "Splitter Manifold", desc: "A brass 4-way splitter gets t’readed onto da main spigot, and one tap now feeds 4 hoses at once. Opened all da way, da house line gives maybe 12 gallons a minute, split into 3 gallons apiece, which is less dan anybody was promised. A valve schedule gets wrote on an index card and taped to da siding. It’s ignored inside 20 minutes." },
  "Balloon Factory": { label: "Balloon Factory", desc: "Balloon production moves from hand-tyin’ on da lawn to a foldin’ table in da garage run by 3 kids. Da line makes about 4 balloons a minute, wit’ a failure rate near 1 in 5 from splits and knots dat let go. Output gets stored in a laundry basket dat holds roughly 60. Da table’s soaked, da floor’s soaked, and it’s da only chore anybody on da block ever volunteered for." },
  "Rapid-Fill Clusters": { label: "Rapid-Fill Clusters", desc: "A quick-fill bunch shows up: 100 balloons on straws, filled from da hose in about 60 seconds and self-sealin’ when ya shake ’em loose. Da garage factory, at 4 a minute, goes obsolete in da time it takes to read da package. One bunch gives about 85 usable rounds. Da hand-tyin’ crew gets reassigned to t’rowin’, which dey figure is a demotion." },
  "Bike Couriers": { label: "Bike Couriers", desc: "Wit’ da front 3 houses from da nearest spigot, resupply falls to kids on bikes carryin’ balloons in handlebar baskets. A basket holds about 15 balloons, and da round trip takes 90 seconds at speeds nobody’s parents approved. Losses in transit run near 20 percent, mostly at da curb cut. One courier gets intercepted and his cargo gets used against his own side." },
  "Wagon Convoys": { label: "Wagon Convoys", desc: "A red wagon replaces da bikes, haulin’ a 5-gallon bucket and 2 laundry baskets, about 110 balloons, in one run. It moves at walkin’ pace and needs 1 puller and 2 escorts wit’ soakers. Da convoy gets ambushed at da halfway point on its second trip. After dat it only travels along da fence line, which adds 40 feet to da route and cuts losses to near nothin’." },
  "Ice Chest Logistics": { label: "Ice Chest Logistics", desc: "Somebody figures out dat water kept in a cooler wit’ 2 bags of ice stays around 40 degrees, like da big lake up by Marquette, while hose water dat sat in da sun comes out near 95. Cold rounds are saved for high-value targets. Da cooler holds 48 quarts and is guarded by a kid on a lawn chair wit’ a clipboard, who logs every withdrawal. Unauthorized access gets ya hit wit’ da contents." },
  "Popsicle Economy": { label: "Popsicle Economy", desc: "Da box of 24 freezer pops in one family’s garage becomes da block’s first currency. A balloon bunch trades for 3 pops, a turn wit’ da biggest soaker for 1, and da other side’s refill schedule for 2. Inflation shows up on day 4, when a second box of 100 gets opened across da street. Da exchange rate never recovers." },
  "Lemonade Stand Treasury": { label: "Lemonade Stand Treasury", desc: "Da west alliance opens a lemonade stand at 50 cents a cup to fund da war, sellin’ to grown-ups on da sidewalk who got no idea what da money’s for. Receipts hit 14 dollars and 25 cents by Saturday afternoon. After cups and mix, net profit is about 9 dollars, which buys 2 more quick-fill bunches. It’s da first war chest on da street wit’ an actual ledger." },
  "Treehouse Water Tower": { label: "Treehouse Water Tower", desc: "A 5-gallon bucket gets hoisted into a treehouse 10 feet up, wit’ a hose run from da bottom of it to da ground as a siphon. Da drop gives about 4 psi at da nozzle, enough for a lazy arc of 6 feet. It’s useless as a weapon and real good as a refill point, ’cause nobody on da ground can reach it. Da rope ladder gets pulled up at night." },
  "Gutter Aqueduct": { label: "Gutter Aqueduct", desc: "Somebody notices da roof gutter along one house is 40 feet long and slopes toward da front. A hose run into da high end out back turns it into an aqueduct dat delivers water, all by itself, to a downspout aimed at da sidewalk. Flow at da outlet is about 5 gallons a minute, and ya can’t aim it at all. Da first person to walk under it is a neighbor bringin’ back a casserole dish." },
  "Driveway Moat": { label: "Driveway Moat", desc: "One household lays a rolled-up tarp across da bottom of its driveway, runs a sprinkler behind it, and floods a strip about 3 inches deep and 12 feet wide. Anybody headin’ for da garage has gotta wade. It holds 2 hours, till da water finds a way under da tarp and into da storm drain. Da owner’s dad backs out at 5:30 and considers da moat defeated." },
  "Sprinkler Minefield": { label: "Sprinkler Minefield", desc: "Six lawn sprinklers get hid under grass clippings in one front yard and hooked to a single valve by da porch. When an attacker gets to da middle, all 6 open at once, coverin’ about 1,200 square feet. Da first test catches 3 enemies and da family cat. After dat da enemy walks around da yard, which da defenders count as a win." },
  "Hose Reel Artillery": { label: "Hose Reel Artillery", desc: "A wall-mounted hose reel gets unbolted and put on a wagon, wit’ 100 feet of hose and a jet nozzle set to its skinniest stream. At house pressure, around 50 psi, it reaches roughly 35 feet and needs 2 operators: one to aim and one to keep da hose from kinkin’. It outranges nothin’ but outlasts everyt’ing, since its tank is da city. Da reel goes back on da wall every night before anybody’s dad gets home." },
  "Pump Patent Dispute": { label: "Pump Patent Dispute", desc: "Two households both claim da pump on da corner’s best soaker as dere own design: 1-inch bore, 6-inch stroke, about 2.6 ounces a stroke. Da case gets heard on a porch by a panel of 3 older kids. Da original goes in as evidence: graph paper at 4 squares to da inch, folded into 8 and dated in crayon. Da panel rules for da kid who drew it and gives da other household production rights, as long as dere’s a credit line on every stock in marker." },
  "Two-Stage Pressure": { label: "Two-Stage Pressure", desc: "A garage workshop adds a second, smaller pump barrel dat tops up da main chamber after it’s charged, pushin’ pressure past anyt’ing da original tank was built for. A kid records 58 feet on a tape measure, den 61, den a burst hose at 64. Da rig gets fixed wit’ electrical tape 3 times in one afternoon. Everybody agrees it’s da future, and nobody wants to stand next to it." },
  "Elastic-Bladder Soakers": { label: "Elastic-Bladder Soakers", desc: "A new design stores pressure in a stretched rubber bladder instead of squeezed air, so da stream stays strong till da tank’s near empty. It fires about 1 liter in 20 seconds at a steady 40 feet, wit’ no fade at da end. Da air-pressure crowd calls it a gimmick for 2 days and den picks up 3 of ’em." },
  "Constant-Pressure Chamber": { label: "Constant-Pressure Chamber", desc: "Somebody builds a chamber dat fills straight from da hose at full house pressure, about 50 psi, and lets go at a steady rate t’rough a trigger valve. Da tank holds 2 liters and refills in 15 seconds at da spigot, against 60 pumps for da old soakers. Pumpin’ is now a skill nobody needs. Da kids wit’ da strongest arms on da block lose dere standin’ overnight." },
  "Neighbor's Pool Treaty": { label: "Neighbor’s Pool Treaty", desc: "Da only in-ground pool on da block holds about 20,000 gallons, and da owners are grown-ups who never agreed to nothin’. A treaty gets worked out t’rough da fence: da alliances can draw up to 5 buckets a day if dey keep all balloon pieces outta da skimmer. Violations get reported by a retired neighbor in a lawn chair. Two buckets in, da treaty’s already in dispute over what counts as a bucket." },
  "Pool Party Summit": { label: "Pool Party Summit", desc: "Leaders of both alliances get invited to a Sunday pool party by a parent who don’t know dere’s a war. Weapons get checked at da gate in a laundry basket, 11 total. Over 3 hours da delegates agree on a no-fire zone around da grill and nothin’ else. Da summit ends when a cannonball off da divin’ board lands 2 feet from da east side’s leader and gets ruled an accident by a vote of 4 to 3." },
  "Chlorine Diplomacy": { label: "Chlorine Diplomacy", desc: "Pool water, at about 3 parts per million of chlorine, turns out to sting da eyes worse dan hose water and fade a green shirt in 1 afternoon. Both sides agree it’s a different category of weapon. A convention gets signed bannin’ chlorinated water above da shoulders. Compliance is high, since da pool owner can yank bucket rights for da whole block in 1 sentence." },
  "Water Bill Crisis": { label: "Water Bill Crisis", desc: "Da monthly bill shows up at da house wit’ da splitter manifold. Usage is up about 9,000 gallons over da same month last year, which at around 7 dollars per 1,000 gallons is a 63 dollar line, cripes, dat nobody can explain away. Da lemonade treasury’s got 11 dollars. A hearin’ gets held at da kitchen table, and da manifold is confiscated pendin’ review." },
  "Parental Intervention": { label: "Parental Intervention", desc: "Parents from 5 households meet on a driveway at 8 in da evenin’, which is da first time some of ’em ever met. Dey set rules: fightin’ only between 10 and 7, no balloons after dark, and no water anybody’s gotta pay for wit’out askin’. Da kids get told by da youngest sibling, who was listenin’ from behind a recyclin’ bin. Compliance is total for about 36 hours." },
  "Spigot Map": { label: "Spigot Map", desc: "Wit’ home water rationed, da kids chart every outdoor spigot inside 4 blocks on da back of a placemat. Da map shows 37 spigots, color-coded by whether da owner’s home durin’ da day, owns a dog, or has ever yelled. Only 6 get starred as usable. Da map gets copied by hand twice, and one copy’s lost to da enemy by Thursday." },
  "Spigot Key Black Market": { label: "Spigot Key Black Market", desc: "A bunch of da starred spigots turn out to have dere handles took off, leavin’ a square stem dat needs a key. A spigot key runs about 8 dollars at da hardware store, which nobody under 12 can get to wit’out a ride. Keys get rented by da hour at 1 dollar, or 3 freezer pops. By da end of da week 2 are in circulation, and 1 is held by a kid who’s got no side and is doin’ real good." },
  "Night Raid": { label: "Night Raid", desc: "At 9:40 at night, 4 east-side kids cross 2 backyards in socks and crank da valve on da west’s sprinkler minefield all da way open. It runs 7 hours. Da west wakes up to a lawn dat squelches and a stockpile of 60 balloons floatin’ in da basket where dey were kept. Nobody gets hit, and it’s still considered da worst t’ing done all summer." },
  "Glow-Stick Balloons": { label: "Glow-Stick Balloons", desc: "To fight after dark against da parent rules, somebody snaps a glow stick into each balloon before fillin’ it. Each stick costs about 20 cents and turns a 6-inch balloon into a green tracer. Now ya can see da rounds comin’ from 40 feet, which defeats da point, and parents can see ’em from 200 feet, which ends da night. It’s da first technology banned by both sides and da grown-ups all at once." },
  "Summer Camp Raid": { label: "Summer Camp Raid", desc: "A day camp from a church 3 blocks over walks 26 campers to da park da same hour da east alliance is resupplyin’ at da park spigot. Da campers are armed wit’ 2 buckets and camp-issued sponges and outnumber da alliance roughly 4 to 1. Contact lasts 12 minutes and da spigot’s lost for da afternoon. Da counselors file an incident report, da first document about da war wrote by anybody over 18." },
  "Garden Collateral": { label: "Garden Collateral", desc: "A tally of collateral damage gets taken for da first time: 1 flattened tomato cage, 14 trampled impatiens, a hydrangea dat’s drifted from pink toward blue for reasons nobody can prove, and a zucchini patch dat’s never been happier. Da gardens dat got watered outnumber da ones dat got damaged 3 to 1. Only da damaged ones complain." },
  "HOA Complaint": { label: "HOA Complaint", desc: "Da homeowners association gets a written complaint citin’ 3 bylaws: standin’ water, unsightly objects in yards, and noise before 8 in da mornin’. It runs 2 pages and includes a picture of a laundry basket. A warnin’ letter goes out to 4 addresses and gets posted on da mailbox cluster. It’s took down inside an hour and reused as a target." },
  "Neighborhood Watch Recruited": { label: "Neighborhood Watch Recruited", desc: "Da neighborhood watch, 7 grown-ups wit’ a group text, gets asked to report water activity along wit’ da usual prowlers and package thefts. Da first week it logs 22 sightings, 19 of ’em kids wit’ buckets and 3 of ’em a sprinkler on a timer. One member turns out to be supplyin’ da west alliance wit’ ice. Da group text gets renamed twice." },
  "Ice Cream Truck Ceasefire": { label: "Ice Cream Truck Ceasefire", desc: "At 3:30 da ice cream truck turns onto da street playin’ its tune, and all fire stops inside about 10 seconds by unspoken agreement. Both sides line up at da window in one line, holdin’ a combined 23 dollars. Da truck stays 6 minutes. A kid holdin’ a full balloon eats a cone one-handed rather dan break da truce, and fire starts up again once da music fades out of hearin’." },
  "Hydrant Diplomacy": { label: "Hydrant Diplomacy", desc: "Da yellow fire hydrant on da corner gets noticed as a strategic asset for da first time. Opened up, it’d put out more dan 1,000 gallons a minute, roughly 100 garden hoses at once. Nobody owns da 5-sided wrench it takes, and nobody’s sure whose side it’s on. Both alliances post a sentry on it anyhow, and da 2 sentries spend da afternoon talkin’ about bikes." },
  "Sprinkler-Cap Hydrant": { label: "Sprinkler-Cap Hydrant", desc: "A parent calls da city and finds out dere’s a legal version: a sprinkler cap bolted onto da hydrant by da fire department, t’rottlin’ flow to about 25 gallons a minute t’rough a spray head. Da request form is 2 pages and needs a grown-up sponsor. It’s approved for a Saturday from 1 to 4. For dose 3 hours da war is suspended and everybody stands in da same spray." },
  "Fire Department Visit": { label: "Fire Department Visit", desc: "An engine company shows up wit’ 4 firefighters to put on da cap. Before fittin’ it dey flush da hydrant wide open for 30 seconds to clear da rust, puttin’ about 500 gallons in da gutter, and every kid on da block watches. Holy wah. No soaker, manifold, or moat ever looks da same again. Da firefighters leave after 20 minutes wit’ 2 cups of lemonade, paid for outta da treasury." },
  "Hydrant Cap Treaty": { label: "Hydrant Cap Treaty", desc: "Both alliances sign a treaty for da capped hydrant: equal time in 15-minute shifts, no messin’ wit’ da cap, and no balloons filled from it, on da theory dat da city agreed to a sprinkler and nothin’ more. It’s witnessed by 2 parents and stapled to da fire department’s form. Da treaty holds for all 4 approved Saturdays. It’s da first agreement of da war dat anybody over 30 has read." },
  "Block Party Armistice": { label: "Block Party Armistice", desc: "Da street closes for da annual block party, wit’ 2 sawhorses and a permit, and an armistice gets signed on a foldin’ table between da potato salad and da beanbag toss. Terms: both alliances dissolve, da spigot keys go back, and da water bill gets split 5 ways. About 60 people show up. Da signin’ pen gets used after to label da leftovers." },
  "Neighborhood Hegemony": { label: "Neighborhood Hegemony", desc: "When da armistice lapses in da next heat wave, one alliance comes out holdin’ da pool rights, da treehouse tower, 3 of da 6 starred spigots, and a lemonade treasury dat’s hit 31 dollars. Nothin’ on da block happens wit’out its okay, includin’ a toddler’s birthday water table. Its leader is 11. Da rest of da neighborhood pays tribute in freezer pops at a rate fixed on graph paper." },
  "The Long Summer": { label: "Da Long Summer", desc: "Da heat runs 41 days above 95 degrees, and da war settles into routine: skirmishes before lunch, a ceasefire at da truck, a raid most Fridays. Da block’s used an estimated 60,000 gallons over normal, about 420 dollars at city rates, and wore out 4 soakers and da grass along da sidewalk. Nobody remembers how it started. Da last week, somebody notices da splash pad at da city park, 2 blocks away, has run all summer wit’ nobody defendin’ it." },
  "Splash Pad Seized": { label: "Splash Pad Seized", desc: "At 97°F da neighborhood splash pad, which runs 60 gallons a minute t’rough 14 ground jets, gets took by 9 kids at 10:02 in da mornin’. Dey hold da center jet by standin’ on it in rotation, bendin’ its 8-foot column sideways into da line. Da parks department’s posted rules, all 11 of ’em, get read out loud by a parent and den ignored. Da pad shuts off on its timer at 8 in da evenin’, which both sides treat as a ceasefire." },
  "Public Pool Occupation": { label: "Public Pool Occupation", desc: "At 108°F, in a city dat owns more umbrellas dan air conditioners, da municipal pool’s 380,000 gallons are da only cold t’ing for 3 miles. Capacity is 250, and da line at openin’ is 412. Dose inside won’t leave, rotatin’ t’rough da shallow end in shifts and holdin’ da lane ropes as a perimeter, while cannonballs go toward da deck about every 40 seconds. Da staff stretch hours to 10 at night rather dan try an eviction." },
  "Lifeguard Neutrality": { label: "Lifeguard Neutrality", desc: "Da 4 lifeguards on duty put out a joint statement from da high chair: dey ain’t takin’ sides, and dey’ll blow da whistle on anybody who runs. Dere jurisdiction ends right at da edge of da deck, 6 feet past da gutter. In 3 hours dey blow da whistle 212 times, split even between factions, which both factions cite as proof of bias. Da lifeguards each drink 2 gallons of water and stay neutral." },
  "Cooling Center Sanctuary": { label: "Cooling Center Sanctuary", desc: "Da library opens as a coolin’ center, held at 68°F, wit’ 120 foldin’ chairs and 3 water coolers. By general agreement it’s sanctuary: nothin’ gets t’rown inside, and loaded soakers go in a bin by da door, which holds 27 of ’em by 2 in da afternoon. Fighters from both sides sit 4 feet apart readin’ da same magazine. Da truce inside is total and ends at da automatic doors." },
  "Open Hydrant Summer": { label: "Open Hydrant Summer", desc: "Somebody opens da hydrant on da corner, and 1,100 gallons a minute cross da street in a white fan 40 feet wide. In 1 hour dat’s 66,000 gallons, about a sixth of da public pool, delivered to one block for free. Kids stand in it, cars drive t’rough it slow wit’ da windows down, and da water department logs da pressure dip inside 4 minutes. Da hydrant’s shut by 3 in da afternoon and open again by 5." },
  "Hydrant Wrench Guild": { label: "Hydrant Wrench Guild", desc: "Da hydrant’s operatin’ nut is a pentagon, 1.5 inches point to flat, picked special so regular wrenches won’t fit. A club of people who own da right wrench forms inside 1 week. Membership is 7, dues are unspoken, and da wrenches run about $30 apiece. Da guild agrees to open hydrants only wit’ a spray cap on, cuttin’ flow to 25 gallons a minute, a concession da water department never asked for and don’t acknowledge." },
  "Street-Wide Mist": { label: "Street-Wide Mist", desc: "Da city puts misting poles along 6 blocks of da commercial strip, 1 nozzle every 3 feet, each puttin’ out half a gallon an hour in droplets fine enough to dry up before dey land. Da air under da mist drops about 10°F. Both factions claim da mistin’ line as a supply route and walk it over and over, a 0.4-mile march dat takes 9 minutes. Nobody gets wet, and da corridor becomes da busiest neutral zone in da war." },
  "Water Main Pressure Drop": { label: "Water Main Pressure Drop", desc: "Wit’ 31 hydrants open across da district, system pressure falls from 65 psi to 22. Second-floor showers quit producin’ water, and da fire department notes, in writin’, dat 20 psi at da hydrant is da least it needs to fight a fire. Da city asks folks to close hydrants for public safety. Inside da hour 19 are closed; da other 12 get declared strategic." },
  "Fire Engine Deluge": { label: "Fire Engine Deluge", desc: "Stuck wit’ hydrants it can’t keep shut, da fire department parks an engine at da block party and opens it up on purpose. Da pump moves 1,500 gallons a minute t’rough a sprinkler attachment at a controlled 50 psi, and 300 folks stand under it for 45 minutes. Officially it’s a community coolin’ event. Both factions figure it’s da fire department pickin’ a side, and neither one can figure out which." },
  "Deck Gun Diplomacy": { label: "Deck Gun Diplomacy", desc: "Da deck gun on top of da engine can put 1,200 gallons a minute onto a spot 200 feet away, which is farther dan any faction’s perimeter. Da captain raises it to 45 degrees and don’t fire. Just bein’ dere, it ends 2 separate standoffs in 20 minutes. Negotiations held inside its reach are real short, and da agreement fits on 1 index card." },
  "Ladder Truck Rain": { label: "Ladder Truck Rain", desc: "An aerial ladder stretches 100 feet over da park at a 70-degree angle and fogs its nozzle straight up. Da water comes down as fake rain over a circle about 90 feet across, at a rate dat shows 3 inches an hour on a rain gauge somebody brought. For da first time, 2 factions stand under da same weather. Da rain quits after 30 minutes when da truck gets sent to a real call, and da grass is dry again by 4:15." },
  "Fountain Occupation": { label: "Fountain Occupation", desc: "Da civic fountain in da downtown plaza, 60 feet across and 18 inches deep, gets waded into by 40 people despite 4 signs sayin’ no. Its pumps turn over da whole basin, about 30,000 gallons, every 2 hours, which da occupiers treat as a free resupply. Da center jet reaches 25 feet and gets fought over up close. Security asks nice twice, den brings a foldin’ chair and watches." },
  "Reflecting Pool Front": { label: "Reflecting Pool Front", desc: "Da reflectin’ pool in front of da government buildin’ is 400 feet long and 2 feet deep, made for lookin’ at, not standin’ in. Wadin’ parties go in from both ends at 11 in da mornin’ and meet at da midpoint, which becomes a front line marked by a floatin’ flip-flop. Da water’s 88°F, barely cooler dan da crowd. Da buildin’s reflection ain’t seen again for 6 days." },
  "River Beach Landing": { label: "River Beach Landing", desc: "Can’t hold da fountains, so one faction moves to da river, landin’ 23 people and 4 blow-up rafts on a gravel bar at 9:40 in da mornin’. Da river runs 64°F at 3 miles an hour, which da landin’ party underestimates by about 2 miles an hour. Fightin’ on da bar is done wit’ 5-gallon buckets, da first weapons in da war too heavy to aim. Da county posts a swift-water advisory, and da beach is abandoned by sunset." },
  "Fireboat Salute": { label: "Fireboat Salute", desc: "Da harbor fireboat, rated at 20,000 gallons a minute from its monitors, goes out for a scheduled salute and puts up 8 arcin’ columns over da river. Da spray drifts 300 feet downwind onto da beach party, soakin’ all 23 of ’em in about 11 seconds. Nobody knows if it was aimed. Da department calls it ceremonial, and da beach party logs it as da biggest single hit of da war." },
  "Water Tower Siege": { label: "Water Tower Siege", desc: "Da neighborhood water tower holds 1,000,000 gallons 150 feet up, which is what gives every tap below it about 65 psi. For 3 days a group camps at its fenced base, gaugin’ da tank by da sound of da overflow pipe and arguin’ over whether ya could drain it all at once. Ya couldn’t; da valve’s locked and 0.8 miles away. Da siege only gets da utility to put in a camera and 2 more padlocks." },
  "Utility Board Hearings": { label: "Utility Board Hearings", desc: "Da water utility board holds a hearin’ on hydrant losses, estimated at 14 million gallons for da month. 212 folks sign up to speak at 3 minutes each, which is 10.6 hours, and da board gives it 2. Testimony splits along faction lines, except for 1 speaker who reads da water tower’s pressure logs out loud in full and gets da only applause. Da hearin’ gets continued to da next Tuesday, when it’s 104°F." },
  "Watering Restrictions": { label: "Watering Restrictions", desc: "Da utility bans lawn sprinklers between 10 in da mornin’ and 6 in da evenin’, wit’ fines startin’ at $50. Da reportin’ line takes 1,840 calls da first week, 71% of ’em about neighbors on da other side of da war. Inspectors hand out 38 warnings. Inside 12 days every front lawn on both sides of da street has gone da same shade of tan, da first t’ing da factions ever agreed on." },
  "Odd-Even Days": { label: "Odd-Even Days", desc: "Waterin’ now goes by address: odd house numbers on Tuesdays and Saturdays, even numbers on Wednesdays and Sundays, before 8 in da mornin’ only. Da street splits accordingly, and da war finally has a calendar. On a Wednesday, da house at number 1418 hoses da house at 1417 and cites da ordinance. Nobody can water on Monday, Thursday, or Friday, which become da war’s rest days." },
  "Pressure Rationing": { label: "Pressure Rationing", desc: "To stretch supply, da utility turns da whole system down from 60 psi to 35. Showers lose about a third of dere flow, garden hoses reach 15 feet instead of 30, and upstairs sinks run in a skinny thread. Every weapon hooked to a spigot gets weaker by da same fraction at da same moment. It’s da most evenhanded t’ing dat’s happened in da war, and both sides complain about it at da next hearin’." },
  "Bottled Water Hoard": { label: "Bottled Water Hoard", desc: "After 31 straight days at or above 110°F, wit’ nights dat don’t drop below 90, da war stops bein’ about t’rowin’ water and starts bein’ about havin’ it. Households buy it by da case, 24 bottles of half a liter each, about 3 gallons, and one garage is found holdin’ 86 cases. Shelves clear by 7 in da mornin’ and restock at 2 in da afternoon from a truck dat gets met in da parkin’ lot. Nobody t’rows a bottle; da water dat was ammo in June is now counted, stacked, and kept outta da sun." },
  "Ice Shortage": { label: "Ice Shortage", desc: "Every bag of ice inside 5 miles is sold by noon, at $3.49 for 10 pounds till it’s $6. Da ice machine at da gas station makes 400 pounds a day and has a line of 17 people wit’ coolers at 6 in da mornin’. Ice ain’t t’rown or dropped down shirts or used for any tactics no more; it goes into da coolers of people who need dere medicine kept cold. Da factions wait in da same line and don’t talk." },
  "Swamp Cooler Bargain": { label: "Swamp Cooler Bargain", desc: "Da evaporative cooler on 1 roof drinks about 10 gallons an hour on a dry day to keep a house 20°F below da outside air. Its owner, who’s on da other side of da war, offers a trade: a hose tap to keep da cooler filled, in exchange for a 3-day halt to fightin’ on da block. Da terms get wrote on da back of a utility bill and signed by 4 households. It’s da first treaty of da war to trade water for peace instead of da other way around." },
  "Grid Truce": { label: "Grid Truce", desc: "Da grid operator posts an emergency alert: demand is at 98% of capacity, and da treatment plant’s pumps run on da same electricity as da air conditioners. Both factions agree to set thermostats at 78°F from 4 to 9 in da evenin’. Da truce is kept by 83% of households, showin’ on da utility’s dashboard as a 40-megawatt dip. For dose 5 hours da war’s whole arsenal sits in da garage, not filled and not fired." },
  "Pump Station Garrison": { label: "Pump Station Garrison", desc: "Da neighborhood booster station, a brick buildin’ wit’ 3 pumps movin’ 4,000 gallons a minute each, loses power for 22 minutes in a rollin’ blackout, and pressure on da hill drops to nothin’. Da next day a garrison of 6 folks from both sides sits outside da station wit’ foldin’ chairs and a cooler, guardin’ nothin’ in particular. Da utility puts in a 500-kilowatt backup generator inside da week. Da garrison takes da credit." },
  "Canal Front": { label: "Canal Front", desc: "Da war reaches da irrigation canal at da edge of town, 40 feet wide and 6 feet deep, carryin’ 800 cubic feet a second of water dat belongs to farmers 30 miles downstream. Swimmin’ in it is illegal and dangerous, and posted as such every 500 feet. Da factions stick to fillin’ buckets from da concrete lip and t’rowin’ ’em across, a range of exactly 1 canal. Da ditch rider patrols in a pickup twice a day and writes down license plates." },
  "Drainage Ditch Trenches": { label: "Drainage Ditch Trenches", desc: "Wit’ da canal patrolled, fightin’ drops into da drainage ditches, 4 feet deep, which run behind 3 subdivisions and hold no water at all. Dey’re good for cover and nothin’ else. Each side digs a sump in da bottom and fills it from a 50-foot garden hose, makin’ a puddle of about 20 gallons dat dries up in 90 minutes. Da war’s got trenches now, and dey’re da driest spots in it." },
  "Stormwater Tunnels": { label: "Stormwater Tunnels", desc: "Under da ditches runs da storm drain system: concrete pipes 6 feet across, dry for 97 days and 7°F cooler dan da street. A faction finds out a whisper at 1 grate can be heard 800 feet away at da next. Nobody fights inside, ’cause da grates are welded shut and one thunderstorm could fill da pipes in 10 minutes. Da tunnels are for listenin’ only, done by lyin’ on da pavement wit’ an ear to da grate." },
  "Center-Pivot Artillery": { label: "Center-Pivot Artillery", desc: "A farmer’s center-pivot irrigator, a quarter mile long on 8 wheeled towers, sweeps a 125-acre circle every 20 hours at about 800 gallons a minute. A faction from town learns its schedule and times raids so da outer end passes over ’em at 11 in da mornin’. At 9 feet up and about 7 feet a minute, it’s da slowest heavy artillery ever fielded and da most accurate. Asked about it, da farmer says he don’t care as long as da corn gets watered." },
  "Crop Duster Air Raid": { label: "Crop Duster Air Raid", desc: "An ag pilot, hired to spray fields 2 miles out, gets talked into it by $200 and a case of cold pop to make 1 pass over da park wit’ a 300-gallon hopper of plain water. Da plane crosses at 110 miles an hour and lets go in 4 seconds. Da load spreads into a 60-foot swath of drizzle dat hits da ground mostly as a rumor. Da aviation folks call on Monday, and da pilot don’t do it again." },
  "Snowmaking Guns Recalled": { label: "Snowmaking Guns Recalled", desc: "A ski hill 90 miles away, closed for da season, lends da town 2 snowmakin’ guns, each a fan da size of a small car dat atomizes 100 gallons a minute. At 96°F nothin’ freezes; da guns make a cold fog dat brings da park down to 81°F inside 50 feet of da nozzles. Both factions stand in da same cloud. Da resort calls da guns back after 4 days, citin’ its electric bill, which da town agrees to split." },
  "Water Cannon Trucks": { label: "Water Cannon Trucks", desc: "Da city brings out 2 water cannon trucks, on loan from da county, and puts ’em on mobile coolin’. Each carries 2,400 gallons and t’rows 300 gallons a minute to 150 feet, set to a wide fog. Dey make scheduled stops at 12 intersections, 10 minutes each, posted on da city website. Da factions show up at every stop and stand on opposite curbs, and da trucks, on purpose, spray da middle." },
  "City Council Arbitration": { label: "City Council Arbitration", desc: "Da city council takes up da war as agenda item 14, after a zonin’ variance and before da dog park. It rules 5 to 2 dat hydrants can only be opened wit’ city spray caps, dat da fire department will run 3 coolin’ events a week, and dat both factions will sit on a new 9-member heat committee. Da committee meets once, in da library, at 68°F. Its minutes run 11 pages and got no water in ’em." },
  "Municipal Pump Standard": { label: "Municipal Pump Standard", desc: "Da pump from da graph paper, still drawn at 4 squares to da inch, gets scaled up by a factor of 12: da 1-inch bore becomes 12 inches and da 6-inch stroke becomes 72, keepin’ da proportions exact. One pull now moves about 8,120 cubic inches, roughly 35 gallons, instead of 2.6 ounces. Da council adopts it as da reference design for emergency hand pumps and writes it into da city code as Section 14-212. Da original sheet goes in da record as Exhibit A, and nobody asks who drew it." },
  "Pump Works": { label: "Pump Works", desc: "A shop in da industrial park tools up to build da standard pump, castin’ a 12-inch cylinder and fittin’ a handle dat takes 2 grown-ups to pull t’rough its full stroke. Da first 10 units ship to fire stations and coolin’ centers at $4,800 apiece. Each fills a 55-gallon drum in 2 strokes, wit’ some left over. Da shop hires 14 people and hangs da original diagram, framed, on da wall by da time clock." },
  "Reservoir Rumors": { label: "Reservoir Rumors", desc: "Da city reservoir, 6 miles north, stands at 41% of capacity, and a rumor goes around dat it’ll be empty in 19 days. Da utility’s real number is 140 days at current use, but da rumor gets shared 22,000 times and da correction 900. Folks drive out to look at da exposed shoreline, a pale band 30 feet tall. Each faction blames da other for startin’ da rumor, and both are partly right." },
  "Regional Compact": { label: "Regional Compact", desc: "Da city and 4 neighborin’ towns sign a regional water compact at 2:30 in da afternoon in an air-conditioned hotel ballroom. It sets shared drought triggers, moves 3,000 acre-feet between systems, and promises no town will cool a neighbor’s kids wit’ its hydrants wit’out askin’ first. Da document is 64 pages long. Da kids, who nobody asked, keep fightin’ under whichever town’s pressure is highest dat day." },
  "Water Rights Court": { label: "Water Rights Court", desc: "A farmer 30 miles downstream sues da city over da canal, citin’ a water right dated 1911 dat’s older dan da city’s by 36 years. Under first in time, first in right, da older claim gets served first in a shortage, and da judge agrees. Da city has gotta release 1,200 acre-feet it planned to keep. Hydrants in town get lockin’ caps da next week, and da war’s oldest grudge turns out to belong to somebody else." },
  "Metro Hegemony": { label: "Metro Hegemony", desc: "Da metro water authority swallows 11 smaller utilities and now serves 2.3 million people from one control room. Every tap, hydrant, splash pad, and coolin’ center in da war answers to 1 set of pressure setpoints. Da neighborhood factions find out dere real opponent is a dispatcher on a 12-hour shift who can drop dere pressure 10 psi wit’ a mouse click. Dey send a joint letter, and it gets logged." },
  "The Hot Summer": { label: "Da Hot Summer", desc: "Da summer ends wit’ 67 days over 100°F, 3 rollin’ blackouts, 2 lawsuits, 1 compact, and a pump standard in da city code. Da utility says it delivered 9% more water dan any year on record and still ran short. Nobody can say who won, ya know; da splash pad’s back on its timer and da hydrants wear locks. Da one t’ing everybody agrees on is da next fight: da water comes down a pipe 233 miles long, and da pipe ain’t da city’s." },
  "Aqueduct Seizure": { label: "Aqueduct Seizure", desc: "Da war outgrows da block and takes its first piece of real infrastructure: an aqueduct 233 miles long dat runs downhill on gravity da whole way. Da seizin’ faction holds 1 intake gate for 36 hours wit’ 11 people and a foldin’ table. Nobody downstream notices for 2 days, ’cause da channel still has dat much water in transit. Da occupiers learn dat ownin’ da pipe ain’t da same as ownin’ what’s in it." },
  "River Diversion": { label: "River Diversion", desc: "An upstream faction cuts a diversion channel 1,400 feet long and pulls 40 cubic feet per second off a river carryin’ 310. Da downstream side files a complaint, den a second complaint, den digs its own channel 2 miles farther down to take back 25. Both channels are dry by August. Da river, meanwhile, has become da most sued-over 9 miles in da county." },
  "Dam Occupation": { label: "Dam Occupation", desc: "A concrete dam 210 feet high gets occupied by a faction wit’ no idea how to run it. Dey hold da control room 3 days and open no gates, ’cause da operatin’ manual is 640 pages and da first 80 are about safety. Da reservoir behind ’em rises 4 inches from inflow alone. Dey leave havin’ changed nothin’ but da control room thermostat, which dey set to 68." },
  "Great Lakes Compact": { label: "Great Lakes Compact", desc: "Eight states and 2 provinces bind demselves to a compact over roughly 5,400 cubic miles of fresh water, Superior holdin’ most of it, and agree almost none of it can leave da basin; ratification takes 3 years. Heat at dis tier looks like da 2021 Pacific Northwest dome: 116°F in a city built for summers near 80, where da fight ain’t over who gets wet but over who can reach a coolin’ center. Da compact holds. Da lakes don’t move an inch." },
  "Colorado River Treaty": { label: "Colorado River Treaty", desc: "Da 1922 split gets reopened: about 15 million acre-feet a year, divided among 7 states on da assumption da river carries dat much. It don’t, and hasn’t for most of a century. Da negotiators meet in a hotel ballroom kept at 71°F and spend 11 days on da last 200,000 acre-feet. Da treaty gets signed, and da river goes on deliverin’ about 12 million." },
  "Aquifer Drilling Race": { label: "Aquifer Drilling Race", desc: "Both factions drill for da same aquifer, 380 feet down, from lots 60 feet apart. Each new well drops da other guy’s water, so da race becomes one of depth: 500 feet, den 720, den a rig rented at $38,000 a week. Da aquifer took about 10,000 years to fill and now drops 3 feet a year from da contest alone. Both sides call dere pumpin’ sustainable." },
  "Pipeline Campaign": { label: "Pipeline Campaign", desc: "Da campaign lays a pipeline: 48-inch steel, 186 miles, at about 1 mile a day, wit’ crews workin’ only before 10 in da mornin’. Heat at dis tier matches Chicago in July 1995, 106°F in da shade, nights dat never cooled, and upper-floor apartments wit’ windows painted shut. Da lesson dat city learned was to knock on doors, and da pipeline authority makes it policy. Da line’s finished 7 months late, which da annual report calls a schedule adjustment." },
  "Tanker Convoys": { label: "Tanker Convoys", desc: "Water moves by road now, in convoys of 9 tanker trucks at 6,500 gallons each, runnin’ a 140-mile loop twice a day. A convoy delivers about 117,000 gallons daily and burns 1,100 gallons of diesel doin’ it. A rival faction sets up a checkpoint at da county line and charges a toll of 1 bottle a truck. Da toll gets paid, logged, and eventually audited." },
  "Water Barons": { label: "Water Barons", desc: "Control bunches up into 4 families who hold da rights, da wells, and da trucks. A baron’s holdings are measured in acre-feet, and da biggest claims 340,000 of ’em on da strength of a filin’ from 1887. Water sells at $1,200 an acre-foot in a dry year and $2,900 in a drier one. Da barons meet quarterly, never in summer, and always someplace wit’ a lake view, like a camp on Superior." },
  "Canal Empire": { label: "Canal Empire", desc: "Da barons’ holdings get joined by open canal: 1,100 miles of it, concrete-lined, 40 feet wide at da top and droppin’ about 1 foot per mile. Under desert sun an open canal loses roughly 6 feet of depth a year to evaporation, so a lot of da empire’s effort goes to waterin’ da sky. Boundaries get redrawn to follow da canals. Da canals follow da grade, which nobody negotiated wit’." },
  "Aquifer Fortress": { label: "Aquifer Fortress", desc: "One faction quits fightin’ for surface water and walls off an aquifer instead: 14 wells inside a fenced compound of 2,600 acres, watched by 38 sensors dat report da water table every 15 minutes. At current rates da fortress can pump for 11 years before da water falls below its intakes. Da fence cost $6 million. Da aquifer runs 40 miles past it every direction, which da fence don’t address." },
  "Reservoir Kingdom": { label: "Reservoir Kingdom", desc: "Da biggest reservoir in da region, about 26 million acre-feet at full pool, gets declared a kingdom wit’ its throne room in da dam. Full pool ain’t been seen in 40 years, and da bathtub ring on da canyon walls, about 150 feet tall, serves as da official history. Succession goes by elevation: below 1,050 feet above sea level, da crown passes to a committee. Da committee meets weekly." },
  "Cloud Seeding Arms Race": { label: "Cloud Seeding Arms Race", desc: "Da war goes airborne. Twin-engine planes fly into passin’ cumulus and burn silver iodide flares, a trick dat at best adds 5 to 15 percent to rain from clouds dat were gonna rain anyhow. Both sides send 6 planes into da same storm, and both claim da 0.4 inches dat falls. A neutral rain gauge gets put on da border and knocked over inside 3 weeks." },
  "Silver Iodide Embargo": { label: "Silver Iodide Embargo", desc: "One side corners da supply of silver iodide, a yellow powder used a few grams a flight, and declares an embargo. Da stockpile is 340 kilograms, enough for about 70,000 flares. Da other side switches to dry ice, which works, and to table salt, which mostly don’t. Da embargo gets lifted after 9 months wit’ nobody able to prove it made a difference, which is also true of da seedin’." },
  "Iceberg Towing": { label: "Iceberg Towing", desc: "A flat-top iceberg 1 mile long, half a mile wide, and 1,000 feet thick gets hooked to 3 oceangoin’ tugs and pulled toward a thirsty coast at 1 knot. Da trip is 6,000 nautical miles and takes about 250 days, and da berg loses roughly half its mass to warm water on da way. What shows up still holds about 50 billion gallons. Nobody’s built a way to get it ashore, ya know, which comes up at da first press conference." },
  "Desalination Coast": { label: "Desalination Coast", desc: "Da coast gets lined wit’ reverse-osmosis plants, each makin’ about 50 million gallons a day by forcin’ seawater t’rough membranes at around 800 psi. For every gallon kept, a plant sends back roughly 1 gallon of brine at twice da salt of da sea. Dere’s 14 plants on a 90-mile stretch, and da fish notice before da regulators do. Da water’s excellent and runs about $2,000 an acre-foot." },
  "Fog Harvesting Frontier": { label: "Fog Harvesting Frontier", desc: "On coastal ridges where it hardly ever rains, mesh nets 40 meters long and 10 high get strung into da fog. At about 1 liter per square meter per day, one net gives 400 liters, enough for roughly 20 careful people. Da frontier runs 30 miles of ridgeline, and claims get staked by da square meter. Da first land fight is over a net standin’ in another net’s fog shadow." },
  "Dew Collectors Guild": { label: "Dew Collectors Guild", desc: "Below da fog line a guild forms around dew: cooled panels dat give off heat into a clear night sky and collect about 0.3 liters per square meter by dawn. Joinin’ takes 100 square meters of panel and 3 years of logged sunrises. Da guild’s 6,000 members make roughly 180,000 liters a night, less dan one desalination plant makes in 2 minutes. Da guild charter calls dis artisanal." },
  "Atmospheric Water Mines": { label: "Atmospheric Water Mines", desc: "Da air itself gets mined. Refrigerated condensers da size of shippin’ containers pull about 2,000 liters a day each outta humid air, burnin’ roughly 0.5 kilowatt-hours per liter. A mine of 250 units gives 500,000 liters a day and draws as much power as a small town. Claims get filed on air masses by da cubic mile, and da claims leave at 12 miles an hour, which da registry ain’t solved yet." },
  "Monsoon Capture": { label: "Monsoon Capture", desc: "Da factions turn to da monsoon, which dumps about 80 inches on a single basin in 4 months. Capture means catchment: 1,900 check dams, 60,000 rooftop cisterns, and a reservoir dat fills in 11 days and spills on da 12th. Most of da rain still gets to da sea, where it was headed anyhow. Da captured share is 8 percent, which is enough to start a new war over da other 92." },
  "Hurricane Harvest": { label: "Hurricane Harvest", desc: "A hurricane comin’ ashore can drop on da order of 20 trillion gallons, and da harvest plan is to keep some of it. Spillways get opened ahead of time to make 900,000 acre-feet of room. Da storm delivers more dan dat to 1 county in 36 hours, most of it into da streets. Da harvest is declared a partial success on da grounds dat da reservoirs are, in fact, full." },
  "Continental Soak Grid": { label: "Continental Soak Grid", desc: "All of it gets wired together: aqueducts, canals, pipelines, desalination plants, and dew panels, run from one control room wit’ 1,400 screens. Da grid moves about 90 million acre-feet a year across 3 time zones, routin’ water by price da way electricity gets routed by load. A valve shut in one state shows up as a pressure surge 700 miles away. For da first time da whole continent could soak one neighborhood, and da neighborhood has asked it not to." },
  "Pump Dynasty": { label: "Pump Dynasty", desc: "Da 12-inch municipal pump becomes da house design of a dynasty dat now supplies 70 percent of da grid’s pumpin’ stations. Every unit comes from da same drawin’, a 1-inch bore and a 6-inch stroke scaled up by 12, so each stroke moves about 35 gallons, 1,728 times da original 2.6 ounces. Da founding family shows up at every commissionin’. Da heirs get raised on graph paper at 4 squares to da inch and are talked out of drawin’ anyt’ing else." },
  "The First Pump": { label: "Da First Pump", desc: "Da original prototype, a length of 1-inch PVC wit’ a 6-inch stroke and a plunger wrapped in tape, is kept in a case held at 68°F and 45 percent humidity. It ain’t been primed in 31 years. Visitors get 90 seconds wit’ it while a docent explains it moves 2.6 ounces a stroke and could still do it if anybody was allowed to try. Nobody is. Da tape is original and da subject of a long restoration debate." },
  "Hydrologic Map Wars": { label: "Hydrologic Map Wars", desc: "Da last fight before da heat turns deadly is over da map. Watershed boundaries get redrawn by 3 competin’ agencies usin’ different elevation models, and dey disagree on 11,000 square miles of drainage. A ridge line moved 40 feet on paper shifts 60,000 acre-feet a year from one side to da other. Da maps get printed at 1:250,000 and argued over at 1:1." },
  "Death Valley Standoff": { label: "Death Valley Standoff", desc: "Da air hits 130°F, near da highest temperature ever reliably measured on Earth, and da standoff ain’t between factions no more but between people and da afternoon. A person wit’out water or shade can lose 5 percent of body weight in sweat in about 3 hours, and judgment goes first. Nobody sprays anybody. Both sides stop at da same well, fill every container dey got, and wait out da hours from 11 to 6 under whatever roof is closest." },
  "Shade Treaty": { label: "Shade Treaty", desc: "At dis heat shade is da resource, cuttin’ da load on a body in direct sun by da equal of 15°F or more. Da treaty divides it by da square foot: every person gets at least 20 square feet under cover between 10 in da mornin’ and 7 at night, no matter da faction. Tarps, awnings, and underpasses get pooled. Da treaty’s 1 page long and has no enforcement clause, ’cause nobody’s broke it." },
  "Last Cool Water": { label: "Last Cool Water", desc: "Da water in da tank is 71°F, da coolest left for 40 miles, and it gets shared by measure: 250 mL every 15 minutes per person, about 1 liter an hour, which is what a body sweats out in dis heat. Kids and old folks drink first. Nobody fills a bottle for later, and nobody wastes a drop on t’rowin’. Da ledger dat’s counted every splash since da first flicked fingertip now only records who’s had dere share." },
  "Survivability Line": { label: "Survivability Line", desc: "Da wet-bulb temperature hits 35°C, about 95°F at full saturation, and sweat stops coolin’ anybody ’cause it can’t evaporate no more. Past dis line a healthy person wit’out shade has roughly 6 hours before core temperature climbs out of control, and for da old and sick da real limit may sit nearer 31°C. Dere are no factions on either side of it. What’s left of da war is a rotation, every 30 minutes, of who sits nearest da fan, da cold floor, and da wet sheet." },
  "Dhahran Accord": { label: "Dhahran Accord", desc: "Dhahran, Saudi Arabia, July 2003: a dew point of 95°F under 108°F air, and a heat index near 176°F, among da highest ever recorded. Da accord drafted at dis tier has 3 clauses: water is shared, shade is shared, and nobody gets left outside. It’s signed by everybody still able to hold a pen. It’s da last agreement of da water war anybody keeps on purpose, and above 134°F da next page of da record ain’t history no more." },
  "Evaporation Front": { label: "Evaporation Front", desc: "Da Dhahran Accord holds 6 days, which is long enough for da thermometer to hit 135°F and make it pointless. At dis temperature a 2-ounce squirt fired at a target 20 feet away shows up about 10% lighter, and da difference gets logged as a tax. Both sides agree da air is now a third party to da war. Da air don’t sign nothin’." },
  "Mid-Air Loss": { label: "Mid-Air Loss", desc: "At 140°F da tax turns into confiscation. A 3-ounce shot fired across a 30-foot street loses half its mass before da curb and da rest before da target, showin’ up as a warm breeze of no tactical value. Range tables get cut down to 11 feet. Anyt’ing farther dan dat gets filed under weather." },
  "Hot Tap Rounds": { label: "Hot Tap Rounds", desc: "At 150°F da cold tap and da hot tap run da same temperature, and da hot tap’s a little faster. Hose rounds now leave da nozzle hot enough to scald on 2 seconds of contact, so targets dodge instead of soakin’. For da first time in da war, gettin’ missed is what both sides want. Hits drop to 4 an afternoon, and every one gets an apology." },
  "Steam Rounds": { label: "Steam Rounds", desc: "At 180°F a squirted round partly flashes to vapor inside 3 feet of da nozzle, and da shooter’s usually da first one hit. A 40-shot fight makes 1 cloud, 0 confirmed hits, and 2 pairs of fogged glasses, like walkin’ outta da sauna. Doctrine gets amended to require aimin’ away from your own face. It’s da first rule da war’s ever wrote about its own side." },
  "Boil-Over": { label: "Boil-Over", desc: "Da air hits 212°F, and every open container of water at sea level starts boilin’ all by itself. A 5-gallon bucket left on a porch empties itself in about 40 minutes while 3 people watch. Ammo can’t be stored no more, only watched leavin’. Quartermasters start buyin’ lids at $4 apiece." },
  "Kettle Artillery": { label: "Kettle Artillery", desc: "At 230°F da kettle is da only vessel dat still makes sense, since it was built for dis. Kettles get lobbed by hand over a 6-foot fence to an average range of 14 feet, each loaded wit’ 1.5 quarts, of which about 1 cup shows up. Da whistle gives 4 seconds of warnin’, which is considered sportin’. Losses run 9 kettles a week at $22 apiece." },
  "Pressure Cooker Siege": { label: "Pressure Cooker Siege", desc: "At 250°F da only liquid water on da block is inside pressure cookers holdin’ 15 psi. Each side’s got one 6-quart cooker, and neither can open it wit’out losin’ most of what’s in it as steam in about 2 seconds. Da siege lasts 11 days. It’s just 2 households watchin’ 2 pressure gauges across a lawn." },
  "Geyser Farming": { label: "Geyser Farming", desc: "At 300°F da war quits da kitchen and goes after da ground. A big geyser puts out about 8,400 gallons an eruption, roughly 1,680 buckets, on a schedule ya can print. Da water flashes to steam 15 feet up, so neither side collects any; dey fight over da schedule instead. Eruptions get handed out every other one, 90 minutes apart." },
  "Superheated Jets": { label: "Superheated Jets", desc: "At 400°F water stays liquid only in lines held above about 250 psi. Jets get fired from sealed pipe, flash to steam 1 inch past da nozzle, and swell about 1,600 times in volume, so a 1-cup shot turns into a 25-gallon cloud. Range is pretty much 0 feet. Accuracy, inside dat range, is total." },
  "Oven Doctrine": { label: "Oven Doctrine", desc: "At 500°F da outdoors is as hot as a pizza oven, or a pasty oven, and doctrine gets rewrote to match. All water is kept in sealed vessels rated to 680 psi and never opened. Fights are just both sides holdin’ up dere gauges across a 40-foot street. Da higher readin’ wins, and da loser’s water is confirmed to be right where it was." },
  "Supercritical Water": { label: "Supercritical Water", desc: "At 705°F and 3,200 psi, water passes its critical point and quits bein’ either liquid or gas. It fills any container even, dissolves a little of da container, and can’t be squirted, ’cause dere’s no difference no more between da stream and whatever’s around it. Da rules committee spends 3 weeks on whether a hit’s still possible. It rules yah, in principle, and records 0." },
  "Venusian Drought": { label: "Venusian Drought", desc: "At 867°F da surface of Earth matches Venus, which prob’ly had oceans once and now keeps about 0.002% water vapor in its air. Da oceans here start da same trip, at roughly 1 inch of depth a day. Da war is suspended for lack of materiel. Both sides write to Venus for advice, which has had 4 billion years to get a reply ready." },
  "Molten Metal Moratorium": { label: "Molten Metal Moratorium", desc: "At 1,221°F aluminum melts, takin’ every canteen, pop can, and soaker frame on da block wit’ it. A moratorium on metal ordnance gets declared after an aluminum bucket slumps into a disk 14 inches across durin’ routine resupply. Da last 40 gallons of surface water get moved into steel tanks, which have about 1,300°F of margin left. Both sides agree not to t’row anyt’ing dat might drip." },
  "Lava Lake Treaty": { label: "Lava Lake Treaty", desc: "At 2,000°F da ground runs as lava, and da only standin’ liquid on da planet is rock. A treaty gets signed on an iron plate 12 feet across, picked ’cause iron’s got 800°F of margin left. It says lava ain’t water and can’t be t’rown. It passes 2 to 0, and enforcement is left to da lava." },
  "Pump Ruins": { label: "Pump Ruins", desc: "At 2,800°F iron melts, and every descendant of da pump goes wit’ it, from municipal stations to da dynasty’s flagships, all built on da same original drawin’. Da castings slump thickest-last, and da 6-inch stroke sags into a puddle dat once moved 2.6 ounces a pull. Da last t’ing ya can recognize in each is da 1-inch bore, a round hole dat holds its shape for about 9 minutes. Drawn at 4 squares to da inch, it was exactly 4 squares wide." },
  "Plasma Hose": { label: "Plasma Hose", desc: "At 10,000°F water molecules come apart into hydrogen and oxygen and den lose dere electrons, so a hose fires glowin’ plasma instead of a stream. A test shot of 1 gallon makes a flash ya can see 40 miles away, like da northern lights over da Keweenaw, and no wetness at any range. Earth’s last 6 gallons of water get spent calibratin’ it. Da planet’s now officially dry, eh, and da war starts lookin’ up." },
  "Comet Harvest": { label: "Comet Harvest", desc: "Wit’ da air at 50,000°F and Earth outta water, da war goes to da comets, which are up to 80% water ice. A comet 1 mile across holds on da order of 100 billion gallons, more dan both sides have fired in dere whole history put together. 2 claims get filed on da same comet 11 minutes apart. It gets split by a line drawn down da middle in marker, and harvested on da way out, which is da only direction comets go." },
  "Europa Drilling": { label: "Europa Drilling", desc: "Back home da thermometer reads 100,000°F, so da war moves to Europa, whose ocean holds about 2 times Earth’s water under ice roughly 12 miles thick, like Superior in a hard February only worse. Da first borehole takes 7 years to reach liquid. Da first 500 gallons pumped out get fired at da other side’s drill rig, 400 feet away, outta habit. It’s da first water war fought in da outer solar system, and it’s scored under da old rules." },
  "Ring Ice Barges": { label: "Ring Ice Barges", desc: "At 500,000°F da fight moves to Saturn’s rings, which are about 99% water ice, 170,000 miles wide, and most places under 100 feet thick. Barges 2 miles long skim ’em for ammo of unusual purity. A rulin’ limits each side to 1 ring at a time. Nobody can agree how many rings dere are, and da count runs from 7 to several thousand dependin’ on who’s claimin’." },
  "Oort Cloud Claims": { label: "Oort Cloud Claims", desc: "At 1,000,000°F everyt’ing closer to da Sun is spoke for, so da war files on da Oort cloud: maybe a trillion icy bodies scattered out to about 1.5 light-years. Claims go out by radio and take up to 18 months to get dere, so every filin’ is outta date when it lands. Da registry hits 3.8 million pages. Every page is disputed, includin’ da index." },
  "Hydrogen-Oxygen Synthesis": { label: "Hydrogen-Oxygen Synthesis", desc: "At 2,000,000°F harvested ice don’t survive da trip home no more, so water has gotta be made on arrival from hydrogen and oxygen, 2 parts to 1. Each ounce takes 3.2 grams of hydrogen, 25.2 grams of oxygen, and a spark, and it comes out hot enough to leave again. Output for da first year is 9 ounces. All 9 get fired." },
  "Stellar Water Masers": { label: "Stellar Water Masers", desc: "At 3 million °F da war turns to water masers: clouds of vapor around faraway stars dat amplify microwaves at 22 gigahertz. Ya can’t drink da water or t’row it, but ya can aim it. A beam from a cloud 1,300 light-years away hits da other side’s receivin’ dish and warms it by 0.0001 degree. Dis gets scored as a hit, da first in 6 years." },
  "Solar Corona Spray": { label: "Solar Corona Spray", desc: "At 3.6 million °F da neighborhood is as hot as da Sun’s corona, which sheds about 1.5 million tons of solar wind a second. Both sides run collectors into da spray hopin’ to catch water. Da wind turns out to be near all hydrogen and helium, wit’ oxygen at about 0.1% and never in da right spot. Yield is 0 drops, and da spray gets reclassified as wind." },
  "Stellar Nursery Rights": { label: "Stellar Nursery Rights", desc: "At 10 million °F nothin’ close by can hold water, so rights get sold in stellar nurseries, cold clouds where water freezes onto dust at about minus 400°F, colder dan a Houghton January. One nursery alone makes enough to fill Earth’s oceans about 60 times a day. Parcels get auctioned in blocks of 1,000 light-years. Every winnin’ bid is paid in water da bidder don’t have." },
  "Primordial Hydrogen": { label: "Primordial Hydrogen", desc: "At 27 million °F da war reaches da temperature of da Sun’s core, where hydrogen fuses into helium at about 600 million tons a second. Both sides lay claim to da universe’s hydrogen, which is about 74% of ordinary matter and da half of water nobody’s gotta make. Da ledger now has 2 columns. One is hydrogen, which everybody’s got, and da other is oxygen, which everybody needs." },
  "Last Water Molecule": { label: "Last Water Molecule", desc: "At 1 billion °F oxygen nuclei start breakin’ apart, and da last water molecule in da disputed region turns up: 3 atoms, 18 daltons, unclaimed. Both sides send envoys. It’s held in a magnetic trap for 4 minutes while da terms get read, den comes apart before either side can sign. Da war’s outta ammo for da first time since da spray bottle." },
  "Quark Soup": { label: "Quark Soup", desc: "At 3.6 trillion °F protons and neutrons dissolve into a soup of quarks and gluons. Dere’s no atoms, so dere’s no hydrogen, no oxygen, and nothin’ dat can be wet. A hearin’ gets called on whether up quarks count as water in principle. Da vote is 0 to 0, ’cause da delegates dissolved too, and da question gets tabled for about 13.8 billion years." },
  "Planck Squirt": { label: "Planck Squirt", desc: "At about 2.5×10^32°F, da hottest temperature physics can describe, da forces merge and distance runs outta smaller units. A squirt at dis temperature lasts 1 Planck time, about 5.4×10^-44 seconds, and travels 1 Planck length before dere’s nothin’ left to travel t’rough. It’s da shortest fight on record. Da records don’t survive it." },
  "Before Water": { label: "Before Water", desc: "At about 2.6×10^32°F dere’s nothin’ hotter and nothin’ earlier: no hydrogen, no oxygen, no graph paper, no weather. Every war ever counted, from da first flicked fingertip to da last molecule, fits in a space smaller dan a 1-inch bore, wit’ 0 participants. Nothin’s fightin’, ’cause nothin’ is. Den, for da first time, da temperature starts to fall." },
  "The Next Rain": { label: "Da Next Rain", desc: "Da universe cools below about 3,600°F, and water can hold togedder for da first time since da last war ended. Da first molecules form around 200 million years in, in da leftovers of stars dat never find out what dey were for. 9.1 billion years later, on an unnamed rock 7,900 miles across, it rains: about two miles of it, over roughly a thousand years, which is da longest refill line ever recorded. Nothin’s alive to t’row any of it. Da ledger resets to No Water Drawn, and 4.4 billion years after dat, on graph paper at four squares to da inch, somebody draws a pump." }
});
window.YOOPER.WATER_WAR_BANDS = {
  "Too Cool to Get Wet": "Too Cool to Get Wet, Eh",
  "Incidental": "Just Kinda Happened",
  "Backyard": "Out Back",
  "Neighborhood": "Down Da Block",
  "Municipal": "Whole Town",
  "Continental": "Da Whole Continent",
  "Fiction": "Holy Wah, Dat’s Made Up"
};
